read_genbank:
path <- system.file("extdata", "tutorial", "pUC19c-L09137.2.gb", package = "ggchord", mustWork = TRUE)
python <- Sys.getenv("ALIGNMENT_PYTHON", "python3")
available <- identical(suppressWarnings(system2(python,
  c("-c", shQuote("import Bio")), stdout = FALSE, stderr = FALSE)), 0L)
if (available) {
  result <- read_genbank(path, python = python)
  head(result$seq_data)
} else {
  "Optional Biopython parser is unavailable; no parsed result was computed."
}

