read_delta:
path <- system.file("extdata", "tutorial", "arabidopsis-first-pair.delta", package = "ggchord", mustWork = TRUE)
decoder <- Sys.getenv("DELTA_EXECUTABLE", "show-coords")
if (nzchar(Sys.which(decoder)) || file.exists(decoder)) {
  result <- read_delta(path, executable = decoder)
  head(result$ribbon_data)
} else {
  "Optional show-coords decoder is unavailable; no delta result was computed."
}

